import { LEGACY_START_SPOT, stampVillages } from './terrain-legacy';
import { MOVE, V3_HEIGHT, V3_SIZE, startWorld } from './terrain-v3';

// Versions 1 and 2 are generated by `terrain-legacy.ts` (the 0.7.0 code, moved verbatim in V15a) and are only
// used to move old saves. Terrain version 3 (v15) is the world every new game gets: 128 x 128 x 80.
export { stampVillages };

/** Blocks wide and deep. Tests read this constant. */
export const WORLD_SIZE = V3_SIZE;
export const WORLD_HEIGHT = V3_HEIGHT;
export const CHUNK_SIZE = 16;
export const WORLD_SEED = 20261017;

/** Index of a cell in the flat block array. */
export function cellIndex(x: number, y: number, z: number): number {
  return (y * WORLD_SIZE + z) * WORLD_SIZE + x;
}

export const CELL_COUNT = WORLD_SIZE * WORLD_HEIGHT * WORLD_SIZE;

/**
 * Terrain versions. 1 is the world of 0.4.0 and earlier, 2 adds the villages (0.5.0 to 0.7.0), both 64 x 64 x 64.
 * 3 is the big world of 0.8.0. A saved world records its version; a missing version means 1.
 */
export type TerrainVersion = 1 | 2 | 3;
export const CURRENT_TERRAIN_VERSION: TerrainVersion = 3;

/** Builds the fixed start world (a copy, safe to write). Pure: the same seed always gives the same blocks. */
export function generateTerrain(seed: number = WORLD_SEED): Uint8Array {
  return startWorld(seed).slice();
}

/**
 * The player starts where the 0.7.0 player started, moved into the middle of the big world. Feet position.
 * Computed from the legacy spot, so importing it does not build the big world.
 */
export const START_SPOT = {
  x: LEGACY_START_SPOT.x + MOVE.x,
  y: LEGACY_START_SPOT.y + MOVE.y,
  z: LEGACY_START_SPOT.z + MOVE.z,
};
